import AppKit
import NotchKit
import Observation
import SwiftUI

/// 📋 클립보드 기록: 복사한 글·이미지·파일(클립보드로 찍은 스크린샷 포함)과 파일로 저장된 새 스크린샷을
/// 이 맥에만 기록한다. 노치 탭에서 누르면 다시 복사하고, ⌘⇧V 창(앱 쪽 `ClipboardPopup`)에서 골라 바로 붙여넣는다.
///
/// - `NSPasteboard.changeCount`를 0.5초마다 확인하고, 바뀌었을 때만 내용을 읽는다
/// - 비밀번호 관리자가 표시한 형식(`ConcealedType`·`TransientType`·`AutoGeneratedType`)은 기록하지 않는다
/// - macOS 26부터 다른 앱이 복사한 내용을 읽으면 붙여넣기 허용을 물을 수 있다(처음 한 번 허용)
@MainActor
@Observable
public final class ClipboardModule: NotchModule {
    public let id = "clipboard"
    public let title = "클립보드"
    public let symbol = "doc.on.clipboard"

    public private(set) var items: [ClipboardItem] = []
    /// 고정하지 않은 항목을 몇 개까지 남길지
    public var limit = 50

    @ObservationIgnored private let disk = ClipboardDisk()
    @ObservationIgnored private var poll: Task<Void, Never>?
    @ObservationIgnored private var lastChangeCount = NSPasteboard.general.changeCount
    /// 우리가 쓴 내용은 다시 기록하지 않는다
    @ObservationIgnored private var ownChangeCount = -1

    public init() {}

    public var compactPriority: Int? { nil }

    // MARK: - 켜기·끄기

    public func start() {
        guard poll == nil else { return }
        items = disk.load()
        lastChangeCount = NSPasteboard.general.changeCount
        poll = Task { [weak self] in
            while !Task.isCancelled {
                try? await Task.sleep(for: .milliseconds(500), tolerance: .milliseconds(200))
                self?.check()
            }
        }
    }

    public func stop() {
        poll?.cancel()
        poll = nil
    }

    /// 스냅샷 확인용
    public func showPreview(_ items: [ClipboardItem]) { self.items = items }

    private func check() {
        let pasteboard = NSPasteboard.general
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        guard count != ownChangeCount else { return }
        let types = pasteboard.types?.map(\.rawValue) ?? []
        guard !types.isEmpty, !ClipboardRules.shouldSkip(types: types) else { return }
        guard let content = read(pasteboard) else { return }
        let item = ClipboardItem(content: content, sourceApp: NSWorkspace.shared.frontmostApplication?.bundleIdentifier)
        let result = ClipboardRules.adding(item, to: items, limit: limit)
        disk.discard(result.removed)
        items = result.items
        disk.save(items)
    }

    /// 파일 > 이미지 > 글 순서로 읽는다.
    private func read(_ pasteboard: NSPasteboard) -> ClipboardItem.Content? {
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            return .files(urls.map(\.path))
        }
        let types = pasteboard.types ?? []
        if types.contains(.png) || types.contains(.tiff), let image = NSImage(pasteboard: pasteboard),
           let tiff = image.tiffRepresentation, let png = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]),
           let name = disk.saveImage(png) {
            return .image(name)
        }
        if let text = pasteboard.string(forType: .string), !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return .text(text)
        }
        return nil
    }

    /// 파일로 저장된 스크린샷을 기록에 넣는다(나중에 ⌘⇧V로 이미지로 붙여넣을 수 있게).
    public func addScreenshot(_ url: URL) {
        guard poll != nil, let data = try? Data(contentsOf: url), let name = disk.saveImage(data) else { return }
        let item = ClipboardItem(content: .image(name), sourceApp: ClipboardItem.screenshotSource)
        let result = ClipboardRules.adding(item, to: items, limit: limit)
        disk.discard(result.removed)
        items = result.items
        disk.save(items)
    }

    // MARK: - 동작

    /// 클립보드에 다시 넣는다(붙여넣기는 하지 않음).
    public func copy(_ item: ClipboardItem) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        switch item.content {
        case .text(let text): pasteboard.setString(text, forType: .string)
        case .image(let name):
            if let image = NSImage(contentsOf: disk.imageURL(name)) { pasteboard.writeObjects([image]) }
        case .files(let paths): pasteboard.writeObjects(paths.map { URL(fileURLWithPath: $0) as NSURL })
        }
        ownChangeCount = pasteboard.changeCount
        // 다시 쓴 항목을 맨 앞으로
        items = ClipboardRules.adding(ClipboardItem(id: item.id, content: item.content, isPinned: item.isPinned, sourceApp: item.sourceApp),
                                      to: items, limit: limit).items
        disk.save(items)
    }

    public func togglePin(_ item: ClipboardItem) {
        guard let index = items.firstIndex(where: { $0.id == item.id }) else { return }
        items[index].isPinned.toggle()
        disk.save(items)
    }

    public func delete(_ item: ClipboardItem) {
        disk.discard([item])
        items.removeAll { $0.id == item.id }
        disk.save(items)
    }

    /// 고정한 것은 남기고 지운다
    public func clearUnpinned() {
        let removed = items.filter { !$0.isPinned }
        disk.discard(removed)
        items = items.filter(\.isPinned)
        disk.save(items)
    }

    public func imageURL(_ name: String) -> URL { disk.imageURL(name) }

    // MARK: - 노치 화면

    public func compactLeading() -> AnyView { AnyView(EmptyView()) }
    public func compactTrailing() -> AnyView { AnyView(EmptyView()) }
    public func expanded() -> AnyView { AnyView(ClipboardNotchView(module: self)) }
}

/// 기록 한 줄(노치 탭과 ⌘⇧V 창이 같이 쓴다).
public struct ClipboardRow: View {
    let module: ClipboardModule
    let item: ClipboardItem

    public init(module: ClipboardModule, item: ClipboardItem) {
        self.module = module
        self.item = item
    }

    public var body: some View {
        HStack(spacing: 8) {
            Group {
                switch item.content {
                case .text: Image(systemName: "text.alignleft").foregroundStyle(.secondary)
                case .image(let name):
                    FileThumbnail(url: module.imageURL(name), size: 22)
                        .clipShape(RoundedRectangle(cornerRadius: 3, style: .continuous))
                case .files(let paths): FileThumbnail(url: URL(fileURLWithPath: paths[0]), size: 22)
                }
            }
            .frame(width: 22, height: 22)
            Text(item.summary)
                .lineLimit(1)
                .truncationMode(.tail)
                .frame(maxWidth: .infinity, alignment: .leading)
            if item.isPinned {
                Image(systemName: "pin.fill").font(.caption2).foregroundStyle(.secondary)
                    .accessibilityLabel("고정됨")
            }
        }
        .accessibilityElement(children: .combine)
    }
}

/// 노치 탭: 최근 기록. 누르면 다시 복사한다.
struct ClipboardNotchView: View {
    let module: ClipboardModule

    var body: some View {
        if module.items.isEmpty {
            VStack(spacing: 4) {
                Image(systemName: "doc.on.clipboard").font(.title2).foregroundStyle(.secondary)
                Text("복사한 내용이 여기에 쌓여요").font(.callout.weight(.medium))
                Text("⌘⇧V로 기록 창을 열어 바로 붙여넣을 수 있어요.").font(.caption).foregroundStyle(.secondary)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            ScrollView {
                VStack(alignment: .leading, spacing: 6) {
                    ForEach(ClipboardRules.filtered(module.items, query: "").prefix(20)) { item in
                        ClipboardRow(module: module, item: item)
                            .font(.callout)
                            .contentShape(Rectangle())
                            .onTapGesture { module.copy(item) }
                            .contextMenu {
                                Button("복사") { module.copy(item) }
                                Button(item.isPinned ? "고정 풀기" : "고정") { module.togglePin(item) }
                                Divider()
                                Button("기록에서 지우기") { module.delete(item) }
                            }
                            .help("누르면 다시 복사")
                    }
                }
            }
        }
    }
}
